// ─── MERKEZİ SAYI DOĞRULAYICI ────────────────────────────────────────────────
// Kullanıcı girdisi / localStorage'dan gelen değer her zaman güvenilir sayı olmayabilir
// ("15.", "15,5", "", undefined...). Bu yardımcı, her koşulda sonlu bir sayı döndürür.
function sayiOku(v: any, varsayilan: number = 0): number {
  if (typeof v === "number") return Number.isFinite(v) ? v : varsayilan;
  const n = parseFloat(String(v ?? "").replace(",", "."));
  return Number.isFinite(n) ? n : varsayilan;
}
// Ayarlar objesindeki TÜM oran alanlarını sayıya sabitler. Ayarlar ekranı düzenleme
// sırasında ara değerleri string tutabildiği için ("15." gibi), kaydetme ve yükleme
// anında bu normalizasyon uygulanır — hesap ekranlarına asla string oran sızmaz.
function normalizeSettings(s: any) {
  const out: any = { ...s };
  for (const k of Object.keys(DEFAULT_SETTINGS)) {
    out[k] = sayiOku(s?.[k], (DEFAULT_SETTINGS as any)[k]);
  }
  return out;
}
// PDF/rapor önizlemesi innerHTML ile kuruluyor — başlık/etiket gibi alanlar teorik olarak
// dışarıdan gelen bir metin (fon/hisse adı vb.) içerebileceğinden, HTML'e gömülmeden önce
// kaçırılıyor. Sayısal değerler zaten Intl.NumberFormat'tan geçtiği için dokunulmuyor.
function escapeHtml(v: any): string {
  if (v === null || v === undefined) return "";
  return String(v)
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#039;");
}
// Ödeme planı satırlarına gerçek vade tarihi eklemek için: ay ekleme, ay-sonu taşma
// sorununu (ör. 31 Ocak + 1 ay → 3 Mart yerine 28/29 Şubat) doğru ele alır.
function addMonthsSafe(baslangic: Date, adet: number): Date {
  const y = baslangic.getFullYear();
  const m = baslangic.getMonth() + adet;
  const d = baslangic.getDate();
  const hedef = new Date(y, m, 1);
  const ayinSonGunu = new Date(hedef.getFullYear(), hedef.getMonth()+1, 0).getDate();
  hedef.setDate(Math.min(d, ayinSonGunu));
  return hedef;
}
function tarihFormatla(d: Date): string {
  return d.toLocaleDateString("tr-TR",{day:"2-digit",month:"2-digit",year:"numeric"});
}

